class ManualResource {
    int* data;
public:
    ManualResource(int v) : data(new int(v)) {}  // 1. Acquisition
    ~ManualResource() { delete data; }           // 2. Release (RAII core)

    // === Rule of Five (needed because destructor defined) ===

    // 3. Copy Constructor (Deep copy required)
    ManualResource(const ManualResource& other)
        : data(new int(*other.data)) {}

    // 4. Move Constructor (Transfer ownership)
    ManualResource(ManualResource&& other) noexcept
        : data(std::exchange(other.data, nullptr)) {}

    // 5. Copy Assignment Operator (Idiomatic implementation uses copy/swap)
    ManualResource& operator=(const ManualResource& other) { /* ... */ return *this; }

    // (Move Assignment also required)
};
